266	// extractClientInfo extracts comprehensive client information from the request context.
267	//
268	// This function parses metadata from the gRPC context to extract:
269	// - User Agent: Raw user agent string for detailed parsing
270	// - IP Address: Client IP from X-Forwarded-For or X-Real-IP headers
271	// - Device Type: "mobile", "tablet", or "desktop" (parsed from user agent)
272	// - Operating System: OS name and version (e.g., "iOS 17.1", "Windows 10/11")
273	// - Browser: Browser name and version (e.g., "Chrome 120.0.0.0")
274	//
275	// This information enables users to:
276	// - See all active sessions with device details
277	// - Identify suspicious login attempts
278	// - Revoke specific sessions from unknown devices.
279	func (s *APIV1Service) extractClientInfo(ctx context.Context) *storepb.RefreshTokensUserSetting_ClientInfo {
280		clientInfo := &storepb.RefreshTokensUserSetting_ClientInfo{}
281	
282		// Extract user agent from metadata if available
283		if md, ok := metadata.FromIncomingContext(ctx); ok {
284			if userAgents := md.Get("user-agent"); len(userAgents) > 0 {
285				userAgent := userAgents[0]
286				clientInfo.UserAgent = userAgent
287	
288				// Parse user agent to extract device type, OS, browser info
289				s.parseUserAgent(userAgent, clientInfo)
290			}
291			if forwardedFor := md.Get("x-forwarded-for"); len(forwardedFor) > 0 {
292				ipAddress := strings.Split(forwardedFor[0], ",")[0] // Get the first IP in case of multiple
293				ipAddress = strings.TrimSpace(ipAddress)
294				clientInfo.IpAddress = ipAddress
295			} else if realIP := md.Get("x-real-ip"); len(realIP) > 0 {
296				clientInfo.IpAddress = realIP[0]
297			}
298		}
299	
300		return clientInfo
301	}
302	
303	// parseUserAgent extracts device type, OS, and browser information from user agent string.
304	//
305	// Detection logic:
306	// - Device Type: Checks for keywords like "mobile", "tablet", "ipad"
307	// - OS: Pattern matches for iOS, Android, Windows, macOS, Linux, Chrome OS
308	// - Browser: Identifies Edge, Chrome, Firefox, Safari, Opera
309	//
310	// Note: This is a simplified parser. For production use with high accuracy requirements,
311	// consider using a dedicated user agent parsing library.
312	func (*APIV1Service) parseUserAgent(userAgent string, clientInfo *storepb.RefreshTokensUserSetting_ClientInfo) {
313		if userAgent == "" {
314			return
315		}
316	
317		userAgent = strings.ToLower(userAgent)
318	
319		// Detect device type
320		if strings.Contains(userAgent, "ipad") || strings.Contains(userAgent, "tablet") {
321			clientInfo.DeviceType = "tablet"
322		} else if strings.Contains(userAgent, "mobile") || strings.Contains(userAgent, "android") ||
323			strings.Contains(userAgent, "iphone") || strings.Contains(userAgent, "ipod") ||
324			strings.Contains(userAgent, "windows phone") || strings.Contains(userAgent, "blackberry") {
325			clientInfo.DeviceType = "mobile"
326		} else {
327			clientInfo.DeviceType = "desktop"
328		}
329	
330		// Detect operating system
331		if strings.Contains(userAgent, "iphone os") || strings.Contains(userAgent, "cpu os") {
332			// Extract iOS version
333			if idx := strings.Index(userAgent, "cpu os "); idx != -1 {
334				versionStart := idx + 7
335				versionEnd := strings.Index(userAgent[versionStart:], " ")
336				if versionEnd != -1 {
337					version := strings.ReplaceAll(userAgent[versionStart:versionStart+versionEnd], "_", ".")
338					clientInfo.Os = "iOS " + version
339				} else {
340					clientInfo.Os = "iOS"
341				}
342			} else if idx := strings.Index(userAgent, "iphone os "); idx != -1 {
343				versionStart := idx + 10
344				versionEnd := strings.Index(userAgent[versionStart:], " ")
345				if versionEnd != -1 {
346					version := strings.ReplaceAll(userAgent[versionStart:versionStart+versionEnd], "_", ".")
347					clientInfo.Os = "iOS " + version
348				} else {
349					clientInfo.Os = "iOS"
350				}
351			} else {
352				clientInfo.Os = "iOS"
353			}
354		} else if strings.Contains(userAgent, "android") {
355			// Extract Android version
356			if idx := strings.Index(userAgent, "android "); idx != -1 {
357				versionStart := idx + 8
358				versionEnd := strings.Index(userAgent[versionStart:], ";")
359				if versionEnd == -1 {
360					versionEnd = strings.Index(userAgent[versionStart:], ")")
361				}
362				if versionEnd != -1 {
363					version := userAgent[versionStart : versionStart+versionEnd]
364					clientInfo.Os = "Android " + version
365				} else {
366					clientInfo.Os = "Android"
367				}
368			} else {
369				clientInfo.Os = "Android"
370			}
371		} else if strings.Contains(userAgent, "windows nt 10.0") {
372			clientInfo.Os = "Windows 10/11"
373		} else if strings.Contains(userAgent, "windows nt 6.3") {
374			clientInfo.Os = "Windows 8.1"
375		} else if strings.Contains(userAgent, "windows nt 6.1") {
376			clientInfo.Os = "Windows 7"
377		} else if strings.Contains(userAgent, "windows") {
378			clientInfo.Os = "Windows"
379		} else if strings.Contains(userAgent, "mac os x") {
380			// Extract macOS version
381			if idx := strings.Index(userAgent, "mac os x "); idx != -1 {
382				versionStart := idx + 9
383				versionEnd := strings.Index(userAgent[versionStart:], ";")
384				if versionEnd == -1 {
385					versionEnd = strings.Index(userAgent[versionStart:], ")")
386				}
387				if versionEnd != -1 {
388					version := strings.ReplaceAll(userAgent[versionStart:versionStart+versionEnd], "_", ".")
389					clientInfo.Os = "macOS " + version
390				} else {
391					clientInfo.Os = "macOS"
392				}
393			} else {
394				clientInfo.Os = "macOS"
395			}
396		} else if strings.Contains(userAgent, "linux") {
397			clientInfo.Os = "Linux"
398		} else if strings.Contains(userAgent, "cros") {
399			clientInfo.Os = "Chrome OS"
400		}
401	
402		// Detect browser
403		if strings.Contains(userAgent, "edg/") {
404			// Extract Edge version
405			if idx := strings.Index(userAgent, "edg/"); idx != -1 {
406				versionStart := idx + 4
407				versionEnd := strings.Index(userAgent[versionStart:], " ")
408				if versionEnd == -1 {
409					versionEnd = len(userAgent) - versionStart
410				}
411				version := userAgent[versionStart : versionStart+versionEnd]
412				clientInfo.Browser = "Edge " + version
413			} else {
414				clientInfo.Browser = "Edge"
415			}
416		} else if strings.Contains(userAgent, "chrome/") && !strings.Contains(userAgent, "edg") {
417			// Extract Chrome version
418			if idx := strings.Index(userAgent, "chrome/"); idx != -1 {
419				versionStart := idx + 7
420				versionEnd := strings.Index(userAgent[versionStart:], " ")
421				if versionEnd == -1 {
422					versionEnd = len(userAgent) - versionStart
423				}
424				version := userAgent[versionStart : versionStart+versionEnd]
425				clientInfo.Browser = "Chrome " + version
426			} else {
427				clientInfo.Browser = "Chrome"
428			}
429		} else if strings.Contains(userAgent, "firefox/") {
430			// Extract Firefox version
431			if idx := strings.Index(userAgent, "firefox/"); idx != -1 {
432				versionStart := idx + 8
433				versionEnd := strings.Index(userAgent[versionStart:], " ")
434				if versionEnd == -1 {
435					versionEnd = len(userAgent) - versionStart
436				}
437				version := userAgent[versionStart : versionStart+versionEnd]
438				clientInfo.Browser = "Firefox " + version
439			} else {
440				clientInfo.Browser = "Firefox"
441			}
442		} else if strings.Contains(userAgent, "safari/") && !strings.Contains(userAgent, "chrome") && !strings.Contains(userAgent, "edg") {
443			// Extract Safari version
444			if idx := strings.Index(userAgent, "version/"); idx != -1 {
445				versionStart := idx + 8
446				versionEnd := strings.Index(userAgent[versionStart:], " ")
447				if versionEnd == -1 {
448					versionEnd = len(userAgent) - versionStart
449				}
450				version := userAgent[versionStart : versionStart+versionEnd]
451				clientInfo.Browser = "Safari " + version
452			} else {
453				clientInfo.Browser = "Safari"
454			}
455		} else if strings.Contains(userAgent, "opera/") || strings.Contains(userAgent, "opr/") {
456			clientInfo.Browser = "Opera"
457		}
458	}
